1	import type {AddressInfo} from 'node:net';
2	import {WebSocket} from 'ws';
3	import type {Express} from 'express';
4	import {createServer} from './createServer.js';
5	import type {HalServer, HalServerOptions} from './createServer.js';
6	import {HAL_WS_SUBPROTOCOL} from './ws/subprotocol.js';
7	import type {ChatOrchestrator} from '../orchestration/chatOrchestrator.js';
8	import type {MessageChunk} from '../types/ai.js';
9	import type {ChatSession} from '../types/session.js';
10	import type {SessionStore} from '../types/sessionStore.js';
11	import {InMemorySessionStore} from '../infrastructure/stores/inMemorySessionStore.js';
12	
13	// Shared by the suites that need a real upgrade over a real socket, which no double can stand in for.
14	
15	const servers: Array<{stop: () => Promise<void>}> = [];
16	const clients: WebSocket[] = [];
17	
18	/** An orchestrator that answers once and stops, which is what commits the turn's assistant entry. */
19	export const answeringOrchestrator: ChatOrchestrator = {
20	  processMessage: async () => 'hi',
21	  async *processMessageStream(): AsyncGenerator<MessageChunk> {
22	    yield {type: 'text', text: 'hi'};
23	    yield {type: 'stop', stopReason: 'end_turn'};
24	  },
25	};
26	
27	export async function eventually(check: () => boolean): Promise<void> {
28	  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
29	}
30	
31	/** A store with only the required members, for suites that override an optional store method. */
32	export function delegatingTo(inner: InMemorySessionStore): SessionStore {
33	  return {
34	    create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
35	    get: sessionId => inner.get(sessionId),
36	    delete: sessionId => inner.delete(sessionId),
37	    count: () => inner.count(),
38	    clear: () => inner.clear(),
39	  };
40	}
41	
42	/** Starts an engine on an ephemeral port and returns the URL a client should open. */
43	export async function startEngine(
44	  sessionStore: SessionStore,
45	  onDisconnect?: (sessionId: string) => void
46	): Promise<string> {
47	  const {url} = await startEngineWith({sessionStore, onDisconnect});
48	  return url;
49	}
50	
51	/** Starts an engine with whatever a suite overrides, returning the server itself beside the URL a client should open. */
52	export async function startEngineWith(
53	  options: Partial<HalServerOptions> & Pick<HalServerOptions, 'sessionStore'>
54	): Promise<{url: string; hal: HalServer}> {
55	  const hal = createServer({
56	    app: (() => undefined) as unknown as Express,
57	    wsAuth: async () => ({id: 'u1'}),
58	    orchestrator: answeringOrchestrator,
59	    ...options,
60	  });
61	  await hal.start(0);
62	  servers.push(hal);
63	  const {port} = hal.server.address() as AddressInfo;
64	  return {url: `ws://127.0.0.1:${port}/hal/ws/c1`, hal};
65	}
66	
67	/** Opens a client that the suite's teardown will close, whether its test passed or failed. */
68	export function connectClient(url: string, token = 't'): WebSocket {
69	  const client = new WebSocket(url, [HAL_WS_SUBPROTOCOL, token]);
70	  clients.push(client);
71	  return client;
72	}
73	
74	/** A promise a test settles by hand, to hold a stream or a hook at a point of its choosing. */
75	export function deferred(): {until: Promise<void>; release: () => void} {
76	  let release = (): void => undefined;
77	  const until = new Promise<void>(resolve => {
78	    release = resolve;
79	  });
80	  return {until, release};
81	}
82	
83	/** Resolves with every frame type seen up to and including the first `until` frame. */
84	export function framesUntil(client: WebSocket, until: string): Promise<string[]> {
85	  const seen: string[] = [];
86	  return new Promise<string[]>(resolve => {
87	    client.on('message', raw => {
88	      const {type} = JSON.parse(String(raw)) as {type: string};
89	      seen.push(type);
90	      if (type === until) resolve(seen);
91	    });
92	  });
93	}
94	
95	/** Opens a client that asks one question the moment the socket opens, resolving on the first `until` frame. */
96	export function askOnOpen(
97	  url: string,
98	  {until = 'stream_end', token}: {until?: string; token?: string} = {}
99	): {client: WebSocket; finished: Promise<string[]>} {
100	  const client = connectClient(url, token);
101	  const finished = framesUntil(client, until);
102	  client.on('open', () => client.send(JSON.stringify({type: 'user_message', content: 'hello'})));
103	  return {client, finished};
104	}
105	
106	/** The session id the client's `connected` frame announces, read after the fact; attach it before any frame arrives. */
107	export function announcedId(client: WebSocket): () => string {
108	  let sessionId = '';
109	  client.on('message', raw => {
110	    const frame = JSON.parse(String(raw)) as {type: string; sessionId?: string};
111	    if (frame.type === 'connected') sessionId = frame.sessionId ?? '';
112	  });
113	  return () => sessionId;
114	}
115	
116	/** Tears every socket and server down, so a red test reports instead of hanging the run. */
117	export async function stopEngines(): Promise<void> {
118	  for (const client of clients.splice(0)) client.terminate();
119	  for (const hal of servers.splice(0)) await hal.stop();
120	}
121	
122	/** The one session a store holds, for asserting what survived a close. */
123	export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
124	  return (await store.get(sessionId)) as ChatSession | undefined;
125	}
