}

/** Terminates clients, waits for each server's sockets to drain, then stops it. */
export async function terminateAll(
  clientList: WebSocket[],
  serverList: Array<{stop: () => Promise<void>; wss: {clients: {size: number}}}>,
): Promise<void> {
  for (const client of clientList.splice(0)) client.terminate();
  for (const hal of serverList.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

